<script setup lang="ts">
import {ref} from 'vue';
import {alarm} from './audio';
const props=defineProps<{settings:any;busy:boolean}>();const emit=defineEmits<{save:[settings:any];clear:[]}>();
const tab=ref('Timer'),form=ref(JSON.parse(JSON.stringify(props.settings)));
const lists=['Tomorrow','This week','Planned','Events','Completed','Overdue','Next 7 days','High priority','Medium priority','Low priority','All','Someday'];
function preview(key:'alarm'|'break_alarm'){alarm(Number(form.value.alarm_volume),form.value[key]);}
</script>
<template><div class="ft-tabs"><button v-for="name in ['Timer','General','Lists','Appearance','Account & access']" :class="{active:tab===name}" @click="tab=name">{{name}}</button></div>
<form class="ft-panel ft-settings" @submit.prevent="emit('save',form)">
<template v-if="tab==='Timer'"><h3>Build your focus rhythm</h3><p class="ft-muted">Changes apply to the next session. An active timer keeps its original duration.</p><div class="ft-fields"><label v-for="[key,name,min,max] in [['focus_minutes','Focus duration (minutes)',1,180],['short_break','Short break (minutes)',1,60],['long_break','Long break (minutes)',1,120],['long_after','Long break after sessions',1,12],['daily_goal','Daily goal (minutes)',1,1440]]">{{name}}<input v-model.number="form[key]" type="number" :min="min" :max="max" required></label><label>Timezone<input v-model="form.timezone" placeholder="Asia/Karachi" required></label></div><div class="ft-options"><label v-for="[key,name] in [['auto_focus','Start the next focus session automatically'],['auto_break','Start breaks automatically'],['disable_breaks','Skip break timers']]"><input v-model="form[key]" type="checkbox">{{name}}</label></div><div class="ft-fields"><label>White noise<select v-model="form.noise"><option value="none">None</option><option value="tick">Tic-tac</option><option value="countdown">Countdown</option><option value="wind">Wind ambience</option><option value="classroom">Soft room ambience</option></select></label><label>Noise volume<input v-model.number="form.noise_volume" type="range" min="0" max="100"></label><label>Focus alarm<select aria-label="Focus alarm" v-model="form.alarm" @change="preview('alarm')"><option v-for="a in ['bell','chime','digital','none']">{{a}}</option></select></label><label>Break alarm<select aria-label="Break alarm" v-model="form.break_alarm" @change="preview('break_alarm')"><option v-for="a in ['bell','chime','digital','none']">{{a}}</option></select></label><label>Alarm volume · {{form.alarm_volume}}%<input v-model.number="form.alarm_volume" type="range" min="0" max="100"></label></div><div class="ft-sound-previews"><button type="button" :disabled="form.alarm==='none'||!Number(form.alarm_volume)" @click="preview('alarm')">▶ Preview focus alarm</button><button type="button" :disabled="form.break_alarm==='none'||!Number(form.alarm_volume)" @click="preview('break_alarm')">▶ Preview break alarm</button><small class="ft-muted">Choosing an alarm plays a short preview at the selected volume. None is silent.</small></div></template>
<template v-else-if="tab==='General'"><h3>Your workspace preferences</h3><div class="ft-options"><label v-for="[key,name] in [['add_top','Add new tasks at the top'],['completion_sound','Play a sound when a task is completed'],['groups','Show Groups'],['forest','Show Forest'],['ranking','Show Ranking']]"><input v-model="form[key]" type="checkbox">{{name}}</label></div></template>
<template v-else-if="tab==='Lists'"><h3>Smart lists</h3><p class="ft-muted">Today and Tasks are always available.</p><div class="ft-options"><label v-for="name in lists"><input v-model="form.lists" :value="name" type="checkbox">{{name}}</label></div></template>
<template v-else-if="tab==='Appearance'"><h3>Focus background</h3><div class="ft-options"><label v-for="name in ['plain','lavender','forest']"><input v-model="form.background" type="radio" :value="name">{{name}}</label></div><p class="ft-muted">Light, Dark and System appearance follow the shared Judibas header menu.</p></template>
<template v-else><h3>One Judibas account</h3><p>Focus To Do uses your shared employee login and product access. Company assignments and account changes are managed by your administrator.</p><p class="ft-muted">All productivity features in this workspace are included. There is no separate Premium subscription.</p><h3>Your personal data</h3><p class="ft-muted">Deleting Focus data removes your tasks, sessions, groups you created and preferences. Your Judibas account and other products stay available.</p><button type="button" class="ft-danger" @click="emit('clear')">Delete my Focus data</button><p class="ft-muted">Judibas Focus To Do · Version 1.0</p></template>
<div v-if="tab!=='Account & access'" class="ft-actions"><button class="ft-primary" :disabled="busy">{{busy?'Saving…':'Save preferences'}}</button></div></form></template>
